/**
  * @brief  处理 0x1D CMD_SYSTEM_CONTROL 命令 (Boot 下 JumpToBootloader 幂等回 ACK)
  */
static void iap_handle_sys_ctrl(const minimc_frame_hdr_t *p_req, const uint8_t *p_payload)
{
  if (p_req->payload_len != sizeof(minimc_payload_sys_ctrl_t))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  minimc_payload_sys_ctrl_t ctrl;
  (void)memcpy(&ctrl, p_payload, sizeof(ctrl));
  if (ctrl.action > 2U || (ctrl.target_component != 0U && ctrl.target_component != 1U))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  s_ota.active_session = true;
  iap_send_ack(p_req);
  if (ctrl.action == 1U)
  {
    tmr_delay_ms((ctrl.delay_ms > 100U) ? 100U : ctrl.delay_ms);
#ifndef IAP_HOST_TEST
    NVIC_SystemReset();
#else
    host_test_on_system_reset();
#endif
  }
}

/**
  * @brief  处理 0x20 CMD_OTA_START (144B: 16B 标准头 + 128B ATSG Trailer 擦除前原子准入)
  */
static void iap_handle_ota_start(const minimc_frame_hdr_t *p_req, const uint8_t *p_payload)
{
  if (p_req->payload_len != sizeof(minimc_payload_ota_start_t))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  minimc_payload_ota_start_t req;
  (void)memcpy(&req, p_payload, sizeof(req));

  if (req.target_device != MINIMC_NODE_TH || req.target_component != 1U)
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  if (req.fw_size_bytes > APP_MAX_SIZE || req.trailer.payload_len > APP_MAX_SIZE)
  {
    iap_send_nack(p_req, MINIMC_ERR_OTA_IMAGE_OVERSIZE);
    return;
  }
  if (req.fw_size_bytes == 0U || req.fw_size_bytes != req.trailer.payload_len ||
      !iap_trailer_validate(&req.trailer))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }

  if (bsp_flash_erase_first_app_sector() != FLASH_STATUS_OK ||
      bsp_flash_erase_anchor_sector() != FLASH_STATUS_OK)
  {
    s_ota.state = IAP_STATE_ERROR;
    iap_send_nack(p_req, MINIMC_ERR_OTA_ERASE_FAIL);
    return;
  }

  s_ota.active_session = true;
  s_ota.cached_trailer = req.trailer;
  s_ota.target_fw_len = req.fw_size_bytes;
  s_ota.target_fw_crc32 = req.fw_crc32;
  s_ota.expected_offset = 0U;
  s_ota.last_written_offset = 0U;
  s_ota.has_last_written = false;
  s_ota.has_cached_chunk0 = false;
  s_ota.cached_chunk0_len = 0U;
  s_ota.bytes_written_flash = 0U;
  s_ota.last_err = 0U;
  s_ota.state = IAP_STATE_ERASED_READY;
  iap_send_ack(p_req);
}

/**
  * @brief  将 offset >= 512 的数据块按需擦除 2KB 扇区并写入 Flash 回读校验
  */
static flash_result_t iap_write_flash_chunk(uint32_t offset, const uint8_t *p_data, uint16_t chunk_len)
{
  uint32_t start_addr = APP_START_ADDR + offset;
  uint32_t end_addr = start_addr + (uint32_t)chunk_len - 1U;
  uint32_t first_sector = (start_addr / FLASH_SECTOR_SIZE) * FLASH_SECTOR_SIZE;
  uint32_t last_sector = (end_addr / FLASH_SECTOR_SIZE) * FLASH_SECTOR_SIZE;

  for (uint32_t sec = first_sector; sec <= last_sector; sec += FLASH_SECTOR_SIZE)
  {
    if (sec > APP_START_ADDR && (start_addr <= sec))
    {
      flash_result_t er_res = bsp_flash_erase_sector(sec);
      if (er_res != FLASH_STATUS_OK)
      {
        return er_res;
      }
    }
  }
  return bsp_flash_write_and_verify(start_addr, p_data, chunk_len);
}

/**
  * @brief  将单块固件数据写入 Chunk0 SRAM 缓存或 Flash 区域
  */
static uint8_t iap_store_ota_chunk(uint32_t offset, const uint8_t *p_fw, uint16_t chunk_len)
{
  uint32_t pos = 0U;
  if (offset < CHUNK_MAX_SIZE)
  {
    uint32_t c0_space = CHUNK_MAX_SIZE - offset;
    uint16_t copy_len = (chunk_len < (uint16_t)c0_space) ? chunk_len : (uint16_t)c0_space;
    (void)memcpy(&s_ota.chunk0_buf[offset], p_fw, copy_len);
    s_ota.has_cached_chunk0 = true;
    if ((uint16_t)(offset + copy_len) > s_ota.cached_chunk0_len)
    {
      s_ota.cached_chunk0_len = (uint16_t)(offset + copy_len);
    }
    s_ota.state = IAP_STATE_CHUNK0_CACHED_RAM;
    pos += copy_len;
  }

  if (pos < chunk_len)
  {
    uint32_t flash_off = offset + pos;
    uint16_t flash_len = (uint16_t)(chunk_len - (uint16_t)pos);
    flash_result_t res = iap_write_flash_chunk(flash_off, &p_fw[pos], flash_len);
    if (res != FLASH_STATUS_OK)
    {
      s_ota.state = IAP_STATE_ERROR;
      return (res == FLASH_STATUS_ERR_ERASE) ? MINIMC_ERR_OTA_ERASE_FAIL : MINIMC_ERR_OTA_WRITE_FAIL;
    }
    s_ota.bytes_written_flash += flash_len;
    s_ota.state = IAP_STATE_FLASH_WRITING;
  }
  return 0U;
}

/**
  * @brief  校验 0x21 CMD_OTA_DATA 块偏移与常规最小块长合法性
  */
static uint8_t iap_validate_ota_data_bounds(uint32_t offset, uint16_t fw_len)
{
  if (offset != s_ota.expected_offset ||
      offset > s_ota.target_fw_len ||
      (uint32_t)fw_len > (s_ota.target_fw_len - offset))
  {
    return MINIMC_ERR_OTA_INVALID_OFFSET;
  }
  bool is_last_chunk = ((offset + (uint32_t)fw_len) == s_ota.target_fw_len);
  if (!is_last_chunk && fw_len < CHUNK_MIN_REGULAR_SIZE)
  {
    return MINIMC_ERR_COMMAND_REJECTED;
  }
  return 0U;
}

/**
  * @brief  处理 0x21 CMD_OTA_DATA 分块传输指令 (支持 Chunk0 缓存与重传幂等 ACK)
  */
static void iap_handle_ota_data(const minimc_frame_hdr_t *p_req, const uint8_t *p_payload)
{
  bool state_ok = (s_ota.state == IAP_STATE_ERASED_READY) ||
                  (s_ota.state == IAP_STATE_CHUNK0_CACHED_RAM) ||
                  (s_ota.state == IAP_STATE_FLASH_WRITING);
  if (!state_ok || p_req->payload_len <= sizeof(minimc_payload_ota_data_hdr_t))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }

  minimc_payload_ota_data_hdr_t dhdr;
  (void)memcpy(&dhdr, p_payload, sizeof(dhdr));
  uint16_t fw_len = (uint16_t)(p_req->payload_len - sizeof(dhdr));
  const uint8_t *p_fw = &p_payload[sizeof(dhdr)];
  if (dhdr.chunk_bytes == 0U || dhdr.chunk_bytes > CHUNK_MAX_SIZE ||
      dhdr.chunk_bytes != fw_len || iap_crc16_ccitt(p_fw, fw_len) != dhdr.chunk_crc16)
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  if (s_ota.has_last_written && dhdr.offset == s_ota.last_written_offset)
  {
    iap_send_ack(p_req);
    return;
  }

  uint8_t b_err = iap_validate_ota_data_bounds(dhdr.offset, fw_len);
  uint8_t s_err = (b_err == 0U) ? iap_store_ota_chunk(dhdr.offset, p_fw, fw_len) : b_err;
  if (s_err != 0U)
  {
    iap_send_nack(p_req, s_err);
    return;
  }
  s_ota.last_written_offset = dhdr.offset;
  s_ota.has_last_written = true;
  s_ota.expected_offset += fw_len;
  iap_send_ack(p_req);
}

/**
  * @brief  联合 SRAM Chunk 0 与 Flash 后续段计算全片净荷 IEEE CRC32
  */
static uint32_t iap_calculate_firmware_crc32(void)
{
  uint32_t c0_len = (s_ota.target_fw_len < CHUNK_MAX_SIZE) ? s_ota.target_fw_len : CHUNK_MAX_SIZE;
  uint32_t crc_accum = iap_crc32_accumulate(0xFFFFFFFFU, s_ota.chunk0_buf, c0_len);
  if (s_ota.target_fw_len > CHUNK_MAX_SIZE)
  {
    const uint8_t *p_tail = (const uint8_t *)(const void *)FLASH_PTR(APP_START_ADDR + CHUNK_MAX_SIZE);
    crc_accum = iap_crc32_accumulate(crc_accum, p_tail, s_ota.target_fw_len - CHUNK_MAX_SIZE);
  }
  return ~crc_accum;
}

/**
  * @brief  将固件元数据锚点固化写入 Sector 127 (0x0803F800)
  */
static flash_result_t iap_commit_anchor_metadata(uint32_t fw_crc)
{
  app_anchor_meta_t anchor;
  anchor.anchor_magic = ANCHOR_MAGIC;
  anchor.trailer = s_ota.cached_trailer;
  anchor.firmware_crc32 = fw_crc;
  anchor.anchor_crc32 = iap_crc32_calc((const uint8_t *)&anchor, 136U);
  return bsp_flash_write_and_verify(TRAILER_ANCHOR_ADDR, (const uint8_t *)&anchor, sizeof(app_anchor_meta_t));
}

/**
  * @brief  终止失败的 OTA 会话并清理首扇区与 Anchor 扇区
  */
static void iap_abort_ota_on_error(const minimc_frame_hdr_t *p_req, uint8_t err_code)
{
  (void)bsp_flash_erase_first_app_sector();
  (void)bsp_flash_erase_anchor_sector();
  s_ota.has_cached_chunk0 = false;
  s_ota.cached_chunk0_len = 0U;
  s_ota.bytes_written_flash = 0U;
  s_ota.state = IAP_STATE_ERROR;
  iap_send_nack(p_req, err_code);
}

/**
  * @brief  处理 0x22 CMD_OTA_FINISH 终验与两阶段提交 (先写 Anchor 再写 Chunk0)
  */
static void iap_handle_ota_finish(const minimc_frame_hdr_t *p_req, const uint8_t *p_payload)
{
  if (p_req->payload_len != sizeof(minimc_payload_ota_finish_t))
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  minimc_payload_ota_finish_t fin;
  (void)memcpy(&fin, p_payload, sizeof(fin));

  if (s_ota.state == IAP_STATE_VERIFIED_COMMITTED && fin.fw_crc32 == s_ota.target_fw_crc32)
  {
    iap_send_ack(p_req);
    return;
  }

  bool recv_complete = s_ota.has_cached_chunk0 &&
                       (s_ota.target_fw_len > 0U) &&
                       (s_ota.expected_offset == s_ota.target_fw_len);
  uint32_t calc_crc = recv_complete ? iap_calculate_firmware_crc32() : 0U;
  if (!recv_complete || calc_crc != fin.fw_crc32 || fin.fw_crc32 != s_ota.target_fw_crc32)
  {
    iap_abort_ota_on_error(p_req, MINIMC_ERR_OTA_CRC_MISMATCH);
    return;
  }

  uint32_t c0_len = (s_ota.target_fw_len < CHUNK_MAX_SIZE) ? s_ota.target_fw_len : CHUNK_MAX_SIZE;
  flash_result_t anchor_res = iap_commit_anchor_metadata(fin.fw_crc32);
  flash_result_t c0_res = bsp_flash_write_and_verify(APP_START_ADDR, s_ota.chunk0_buf, c0_len);
  if (anchor_res != FLASH_STATUS_OK || c0_res != FLASH_STATUS_OK)
  {
    iap_abort_ota_on_error(p_req, MINIMC_ERR_OTA_WRITE_FAIL);
    return;
  }

  s_ota.bytes_written_flash = s_ota.target_fw_len;
  s_ota.state = IAP_STATE_VERIFIED_COMMITTED;
  iap_send_ack(p_req);
  if (fin.action_after_verify == 1U)
  {
    tmr_delay_ms(50U);
    app_load(APP_START_ADDR);
  }
}

/**
  * @brief  处理 0x23 CMD_OTA_STATUS 状态查询指令
  */
static void iap_handle_ota_status(const minimc_frame_hdr_t *p_req)
{
  if (p_req->payload_len != 0U)
  {
    iap_send_nack(p_req, MINIMC_ERR_COMMAND_REJECTED);
    return;
  }
  minimc_payload_ota_status_t st;
  iap_get_ota_status(&st);
  iap_send_small_frame(p_req, MINIMC_CMD_OTA_STATUS, (const uint8_t *)&st, sizeof(st));
}

/**
/**
  * @brief  分发已通过帧头与外层 CRC16 校验的 MiniMCProto v2.0 命令
  */
static void iap_dispatch_frame(const minimc_frame_hdr_t *p_hdr, const uint8_t *p_payload)
{
  if (p_hdr->dst_id != MINIMC_NODE_TH)
  {
    return;
  }
  if ((p_hdr->flags & 0x0CU) != MINIMC_FLAG_VERSION_V2 ||
      (p_hdr->flags & MINIMC_FLAG_IS_RESPONSE) != 0U)
  {
    return;
  }

  switch (p_hdr->cmd_id)
  {
    case MINIMC_CMD_GET_VERSION:
      iap_handle_get_version(p_hdr);
      break;
    case MINIMC_CMD_PING:
      iap_handle_ping(p_hdr, p_payload);
      break;
    case MINIMC_CMD_SYSTEM_CONTROL:
      iap_handle_sys_ctrl(p_hdr, p_payload);
      break;
    case MINIMC_CMD_OTA_START:
      iap_handle_ota_start(p_hdr, p_payload);
      break;
    case MINIMC_CMD_OTA_DATA:
      iap_handle_ota_data(p_hdr, p_payload);
      break;
    case MINIMC_CMD_OTA_FINISH:
      iap_handle_ota_finish(p_hdr, p_payload);
      break;
    case MINIMC_CMD_OTA_STATUS:
      iap_handle_ota_status(p_hdr);
      break;
    default:
      iap_send_nack(p_hdr, MINIMC_ERR_UNKNOWN_CMD);
      break;
  }
}

/**
  * @brief  完成一帧接收后的外层 CRC16 校验与分发
  */
static void iap_finalize_rx_frame(void)
{
  uint16_t crc = iap_crc16_update(0xFFFFU, s_rx.raw_hdr, MINIMC_HEADER_SIZE);
  if (s_rx.hdr.payload_len > 0U)
  {
    crc = iap_crc16_update(crc, s_rx.payload, s_rx.hdr.payload_len);
  }
  if (crc != s_rx.rx_crc)
  {
    s_ota.rx_crc_err_count++;
    return;
  }
  s_ota.rx_ok_count++;
  iap_dispatch_frame(&s_rx.hdr, s_rx.payload);
}

/**
  * @brief  处理帧头同步与 12 字节帧头接收阶段 (step 0..2)
  */
static void iap_feed_header_byte(uint8_t byte)
{
  if (s_rx.step == 0U)
  {
    if (byte == MINIMC_SOF_0)
    {
      s_rx.raw_hdr[0] = byte;
      s_rx.step = 1U;
    }
    return;
  }
  if (s_rx.step == 1U)
  {
    if (byte == MINIMC_SOF_1)
    {
      s_rx.raw_hdr[1] = byte;
      s_rx.idx = 2U;
      s_rx.step = 2U;
    }
    else
    {
      s_rx.step = (byte == MINIMC_SOF_0) ? 1U : 0U;
    }
    return;
  }
  s_rx.raw_hdr[s_rx.idx] = byte;
  s_rx.idx++;
  if (s_rx.idx >= MINIMC_HEADER_SIZE)
  {
    (void)memcpy(&s_rx.hdr, s_rx.raw_hdr, MINIMC_HEADER_SIZE);
    if (s_rx.hdr.payload_len > MINIMC_MAX_PAYLOAD_SIZE)
    {
      s_rx.step = 0U;
      return;
    }
    s_rx.idx = 0U;
    s_rx.step = (s_rx.hdr.payload_len == 0U) ? 4U : 3U;
  }
}

/**
  * @brief  向 MiniMCProto v2.0 接收状态机喂入单个字节
  */
void iap_feed_byte(uint8_t byte)
{
  if (s_rx.step <= 2U)
  {
    iap_feed_header_byte(byte);
    return;
  }
  if (s_rx.step == 3U)
  {
    s_rx.payload[s_rx.idx] = byte;
    s_rx.idx++;
    if (s_rx.idx >= s_rx.hdr.payload_len)
    {
      s_rx.step = 4U;
    }
    return;
  }
  if (s_rx.step == 4U)
  {
    s_rx.rx_crc = (uint16_t)byte;
    s_rx.step = 5U;
    return;
  }
  s_rx.rx_crc |= (uint16_t)((uint16_t)byte << 8U);
  s_rx.step = 0U;
  iap_finalize_rx_frame();
}

/**
  * @brief  驱动处理串口升级接收状态机
  */
void iap_upgrade_app_handle(void)
{
  uint8_t byte = 0U;
  while (bsp_uart1_read_byte(&byte))
  {
    iap_feed_byte(byte);
  }
}

#ifndef IAP_HOST_TEST
/**
  * @brief  跳转前外设排空、关闭与中断反初始化
  */
static void app_jump_deinit_hardware(void)
{
  uint32_t to = 50000U;
  while ((usart_flag_get(USART1, USART_TDC_FLAG) == RESET) && (--to > 0U)) {}
#if (DEBUG_LOG_ENABLE == 1)
  to = 50000U;
  while ((usart_flag_get(USART3, USART_TDC_FLAG) == RESET) && (--to > 0U)) {}
#endif
  */
static void test_identity_ping_and_guard_cases(void)
{
  (void)memset(g_sim_flash, 0xFF, sizeof(g_sim_flash));
  iap_init();

  /* G20: 缺少版本位 (Flags=0x01) 必须静默拒绝 */
  uint8_t bad_ver[14] = {0x55, 0xAA, 0x01, 0x03, 0x01, 0x01, 0x04, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
  uint16_t c_bad = iap_crc16_ccitt(bad_ver, 12U);
  bad_ver[12] = (uint8_t)(c_bad & 0xFFU);
  bad_ver[13] = (uint8_t)((c_bad >> 8U) & 0xFFU);
  for (uint8_t i = 0U; i < 14U; i++) { iap_feed_byte(bad_ver[i]); }
  require_true(s_last_tx_len == 0U, "G20 bad version bit must be ignored");

  /* G19: 1025B 超限帧头必须立即丢弃且不影响后续正常帧 */
  uint8_t over_hdr[12] = {0x55, 0xAA, 0x01, 0x03, 0x05, 0x21, 0x04, 0x00, 0x03, 0x00, 0x01, 0x04};
  for (uint8_t i = 0U; i < 12U; i++) { iap_feed_byte(over_hdr[i]); }
  require_true(s_last_tx_len == 0U, "G19 oversize header must be dropped");

  /* 0x01 -> 0x02 VERSION_REPORT */
  send_minimc_req(MINIMC_CMD_GET_VERSION, 1U, NULL, 0U);
  require_true(s_last_tx_len == 30U && s_last_tx[5] == MINIMC_CMD_VERSION_REPORT, "0x02 len and cmd");
  minimc_payload_version_report_t vrep;
  (void)memcpy(&vrep, &s_last_tx[12], sizeof(vrep));
  require_true(vrep.capability_flags == TH_BOOT_CAPABILITY_FLAGS && vrep.boot_id != 0U, "TH boot caps");

  /* 0x03 -> 0x04 PONG */
  uint32_t tok = 0xCAFEBABEU;
  send_minimc_req(MINIMC_CMD_PING, 2U, &tok, 4U);
  require_true(s_last_tx_len == 26U && s_last_tx[5] == MINIMC_CMD_PONG, "0x04 pong");

  /* 0x1D JumpToBootloader 幂等回 0x00 ACK */
  minimc_payload_sys_ctrl_t sc = {2U, 1U, 10U};
  send_minimc_req(MINIMC_CMD_SYSTEM_CONTROL, 3U, &sc, sizeof(sc));
  require_true(s_last_tx_len == 18U && s_last_tx[5] == MINIMC_CMD_ACK, "0x1D ack");
}

/**
  * @brief  测试 0x20 擦除前原子准入负例（错板、坏 CRC、241665B 超限全部零擦除）
  */
static void test_ota_start_negative_zero_erase(void)
{
  uint8_t img[1024];
  fw_trailer_t tr;
  uint32_t crc = 0U;
  build_test_image_and_trailer(img, sizeof(img), &tr, &crc);
  s_erase_count = 0U;

  minimc_payload_ota_start_t start_req;
  (void)memset(&start_req, 0, sizeof(start_req));
  start_req.target_device = MINIMC_NODE_TH;
  start_req.target_component = 1U;
  start_req.fw_size_bytes = 241665U;
  start_req.fw_crc32 = crc;
  start_req.trailer = tr;
  start_req.trailer.payload_len = 241665U;

  /* 241,665B (236KB + 1B) 必须返回 NACK 0x14 且零擦除 */
  send_minimc_req(MINIMC_CMD_OTA_START, 10U, &start_req, sizeof(start_req));
  require_true(s_last_tx_len == 17U && s_last_tx[5] == MINIMC_CMD_NACK, "241665B NACK");
  require_true(s_last_tx[12] == MINIMC_ERR_OTA_IMAGE_OVERSIZE && s_erase_count == 0U, "241665B 0x14 zero erase");

  /* 错板 (MC 0x43500001) 必须返回 NACK 0x06 且零擦除 */
  start_req.fw_size_bytes = sizeof(img);
  start_req.trailer = tr;
  start_req.trailer.board_id = 0x43500001U;
  start_req.trailer.trailer_crc32 = iap_crc32_calc((const uint8_t *)&start_req.trailer, 124U);
  send_minimc_req(MINIMC_CMD_OTA_START, 11U, &start_req, sizeof(start_req));
  require_true(s_last_tx[5] == MINIMC_CMD_NACK && s_last_tx[12] == MINIMC_ERR_COMMAND_REJECTED, "wrong board NACK");
  require_true(s_erase_count == 0U, "wrong board zero erase");
}

/**
  * @brief  发送单块 0x21 CMD_OTA_DATA 的测试辅助函数
  */
static void send_ota_chunk(uint16_t seq, uint32_t offset, const uint8_t *p_data, uint16_t len)
{
  uint8_t buf[MINIMC_MAX_PAYLOAD_SIZE];
  minimc_payload_ota_data_hdr_t dh;
  dh.offset = offset;
  dh.chunk_bytes = len;
  dh.chunk_crc16 = iap_crc16_ccitt(p_data, len);
  (void)memcpy(buf, &dh, sizeof(dh));
  (void)memcpy(&buf[sizeof(dh)], p_data, len);
  send_minimc_req(MINIMC_CMD_OTA_DATA, seq, buf, (uint16_t)(sizeof(dh) + len));
}

/**
  * @brief  测试完整升级闭环、Chunk0 缓存、重传幂等、无 Anchor 防护与两阶段提交
  */
static void test_full_ota_commit_and_anchor_guard(void)
{
  uint8_t img[1024];
  fw_trailer_t tr;
  uint32_t crc = 0U;
  build_test_image_and_trailer(img, sizeof(img), &tr, &crc);

  /* 验证无 Anchor 回退漏洞已修复：即使 0x08004000 有合法向量，无 Anchor 仍返回 false */
  (void)memcpy(&g_sim_flash[APP_START_ADDR - FLASH_BASE_ADDR], img, 64U);
  require_true(!bsp_flash_app_integrity_check(), "raw vector without Anchor must be rejected");

  minimc_payload_ota_start_t start_req = {MINIMC_NODE_TH, 1U, 0U, 0U, sizeof(img), crc, 0x00010200U, tr};
  send_minimc_req(MINIMC_CMD_OTA_START, 20U, &start_req, sizeof(start_req));
  require_true(s_last_tx[5] == MINIMC_CMD_ACK && s_erase_count == 2U, "OTA_START ACK and 2 sectors erased");

  /* 发送首块 512B：缓存在 SRAM，bytes_written 仍为 0，Flash 首扇区仍为 0xFF */
  send_ota_chunk(21U, 0U, &img[0], 512U);
  require_true(s_last_tx[5] == MINIMC_CMD_ACK, "chunk0 ACK");
  minimc_payload_ota_status_t st;
  iap_get_ota_status(&st);
  require_true(st.ota_state == IAP_STATE_CHUNK0_CACHED_RAM && st.cached_chunk0_bytes == 512U && st.bytes_written == 0U,
               "chunk0 cached in SRAM with bytes_written == 0");
  require_true(g_sim_flash[APP_START_ADDR - FLASH_BASE_ADDR] == 0xFFU, "0x08004000 untouched before finish");

  /* 同 offset=0 重传幂等 ACK */
  send_ota_chunk(21U, 0U, &img[0], 512U);
  require_true(s_last_tx[5] == MINIMC_CMD_ACK, "retransmit chunk0 idempotent ACK");

  /* 发送第二块 512B：写入 Flash 0x08004200，bytes_written == 512 */
  send_ota_chunk(22U, 512U, &img[512], 512U);
  require_true(s_last_tx[5] == MINIMC_CMD_ACK, "chunk1 ACK");
  iap_get_ota_status(&st);
  require_true(st.ota_state == IAP_STATE_FLASH_WRITING && st.bytes_written == 512U, "chunk1 flash written");
  require_true(!bsp_flash_app_integrity_check(), "incomplete commit must stay in boot");

  /* 0x22 FINISH 终验通过，两阶段提交 Anchor + Chunk0 */
  minimc_payload_ota_finish_t fin = {crc, 1U, {0U, 0U, 0U}};
  send_minimc_req(MINIMC_CMD_OTA_FINISH, 23U, &fin, sizeof(fin));
  require_true(s_last_tx[5] == MINIMC_CMD_ACK, "OTA_FINISH ACK");
  require_true(bsp_flash_app_integrity_check(), "committed image + Anchor verified");
  require_true(s_jump_addr == APP_START_ADDR, "jumped to APP_START_ADDR");
}

/**
  * @brief  单元测试主入口
  */
int main(void)
{
  test_identity_ping_and_guard_cases();
  test_ota_start_negative_zero_erase();
  test_full_ota_commit_and_anchor_guard();
  printf("[PASS] test_th_boot_ota: all TH Bootloader MiniMCProto v2.0 tests passed!\n");
  return 0;
}
